namespace BlazorApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 4;

    public Task<List<NotificationItem>> GetInitialNotificationsAsync()
    {
        var notifications = new List<NotificationItem>
        {
            new() { Id = 1, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
            new() { Id = 2, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
            new() { Id = 3, Message = "New feature available: Dark mode.", Timestamp = DateTime.UtcNow.AddMinutes(-1) },
        };

        return Task.FromResult(notifications);
    }

    public Task<List<NotificationItem>> CheckForNewNotificationsAsync(int lastKnownId)
    {
        // Simulate occasional new notifications
        var result = new List<NotificationItem>();

        if (Random.Shared.Next(0, 3) == 0)
        {
            var id = Interlocked.Increment(ref _nextId);
            result.Add(new NotificationItem
            {
                Id = id,
                Message = $"New event at {DateTime.UtcNow:HH:mm:ss}",
                Timestamp = DateTime.UtcNow,
            });
        }

        return Task.FromResult(result);
    }
}

